mapper.select:
SELECT DISTINCT cycle_type
FROM task_definition
WHERE mutex_group_id = #{mutexGroupId}
  AND deleted = 0

    AND id <> #{excludeTaskId}

SELECT COUNT(*)
FROM task_definition
WHERE deleted = 0
  AND (
    gray_crowd_id = #{crowdId}
    OR gray_exclude_crowd_id = #{crowdId}
    OR JSON_CONTAINS(filter_allow_crowd_ids, CAST(#{crowdId} AS JSON))
    OR JSON_CONTAINS(filter_exclude_crowd_ids, CAST(#{crowdId} AS JSON))
  )

mapper.update:
UPDATE task_definition
SET status = 'PUBLISHED',
    version = #{nextVersion},
    pending_revision = 0,
    schedule_publish_at = NULL,
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND deleted = 0
  AND status = #{expectedStatus}
  AND version = #{expectedVersion}
  AND pending_revision = #{expectedPending}
